#!/usr/bin/env bash
# SPDX-FileCopyrightText: Cadasto B.V.
# SPDX-License-Identifier: BUSL-1.1
# File-size ratchet: a hand-written Rust file is at most $BUDGET lines (#205).
#
# A file that opens with a `@generated` banner, and a vendored tree under
# docs/specs/, is outside the rule. A file listed in
# scripts/checks/file-size-allow.txt is a known breach: it passes while it
# does not grow past the line count recorded beside it, and the issue named
# beside it splits it. Any other file over $BUDGET fails.
#
# The list only tightens. A listed file that shrank, fell to $BUDGET lines or
# under, or is gone passes with a one-line note, so a pull request that
# splits a file leaves the list alone and conflicts with no other one; the
# scheduled ratchet-tighten workflow runs --update on main and pushes the one
# branch that lowers or removes the entries.
#
# Usage:
#   scripts/checks/file-size.sh              check every tracked .rs file
#   scripts/checks/file-size.sh --files F…   check the named files (the per-edit hook)
#   scripts/checks/file-size.sh --update     lower each entry to its file's length and
#                                            drop the entries back within the budget or
#                                            gone; it never raises or adds one
#   scripts/checks/file-size.sh --self-test  a growth, a shrink, a split, a gone file,
#                                            a new breach and --update
# Exit 1 on an unlisted file over the budget or a listed file that grew, 2 on
# a usage error; 0 otherwise.
#
# No specification governs this: our own design.
set -euo pipefail
cd "$(dirname "$0")/../.."

BUDGET=800
ALLOW=scripts/checks/file-size-allow.txt

note() { printf '  %s\n' "$*"; }

# Builds a scratch repository with one listed file and runs a copy of this
# script there; a file's length is the line count it is given.
self_test() {
  local guard tmp failures=0
  guard="$PWD/scripts/checks/file-size.sh"
  tmp="$(mktemp -d)"
  # shellcheck disable=SC2064 # the path is fixed now, on purpose
  trap "rm -rf '$tmp'" RETURN
  export GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1
  mkdir -p "$tmp/repo/scripts/checks" "$tmp/repo/src"
  cp "$guard" "$tmp/repo/scripts/checks/file-size.sh"
  git -C "$tmp/repo" init -q
  lines() { seq "$2" | sed 's/^/\/\/ /' >"$tmp/repo/src/$1"; }
  allow() {
    printf '# header\n' >"$tmp/repo/$ALLOW"
    [ "$#" -eq 0 ] || printf '%s\n' "$@" >>"$tmp/repo/$ALLOW"
  }
  track() { git -C "$tmp/repo" add -A >/dev/null; }
  expect() {
    local want="$1" label="$2" got=0
    shift 2
    (cd "$tmp/repo" && bash scripts/checks/file-size.sh "$@" >"$tmp/out" 2>&1) || got=$?
    if [ "$got" -ne "$want" ]; then
      echo "file-size: self-test: $label: exit $got, wanted $want" >&2
      sed 's/^/    /' "$tmp/out" >&2
      failures=$((failures + 1))
    fi
  }
  entry() { awk -v p="src/$1" '$1 !~ /^#/ && $2 == p { print $1 }' "$tmp/repo/$ALLOW"; }
  wrong() {
    echo "file-size: self-test: $1" >&2
    failures=$((failures + 1))
  }

  lines big.rs 900; allow "900 src/big.rs #1"; track
  expect 0 "a listed file at its count passes"
  lines big.rs 901; track
  expect 1 "a listed file that grew fails"
  expect 1 "a listed file that grew fails per edit" --files src/big.rs
  expect 1 "a listed file that grew fails per edit by its absolute path" --files "$(cd "$tmp/repo" && pwd)/src/big.rs"
  expect 0 "a file of another checkout is not measured" --files "$tmp/elsewhere/src/big.rs"
  expect 1 "--update refuses a listed file that grew" --update
  [ "$(entry big.rs)" = 900 ] || wrong "--update raised an entry"
  lines big.rs 850; track
  expect 0 "a listed file that shrank passes"
  grep -q 'note:' "$tmp/out" || wrong "a shrink passed with no note"
  [ "$(entry big.rs)" = 900 ] || wrong "a check wrote the list"
  expect 0 "--update lowers a shrunk entry" --update
  [ "$(entry big.rs)" = 850 ] || wrong "--update did not lower the entry to 850"
  lines big.rs 700; track
  expect 0 "a listed file back within the budget passes"
  grep -q 'note:' "$tmp/out" || wrong "a split passed with no note"
  expect 0 "--update drops an entry back within the budget" --update
  [ -z "$(entry big.rs)" ] || wrong "--update kept an entry within the budget"
  allow "900 src/gone.rs #1"
  expect 0 "a listed file that is gone passes"
  expect 0 "--update drops the entry of a gone file" --update
  [ -z "$(entry gone.rs)" ] || wrong "--update kept the entry of a gone file"
  lines new.rs 801; allow; track
  expect 1 "an unlisted file over the budget fails"
  expect 1 "an unlisted file over the budget fails per edit" --files src/new.rs
  expect 2 "--update never adds a new breach" --update
  [ -z "$(entry new.rs)" ] || wrong "--update added a breach"
  { printf '// @generated by a miniature. DO NOT EDIT.\n'; seq 900 | sed 's/^/\/\/ /'; } >"$tmp/repo/src/new.rs"; track
  expect 0 "a generated file over the budget passes"
  lines new.rs 800; track
  expect 0 "a file at the budget passes"
  expect 2 "an unknown flag is refused" --widen

  if [ "$failures" -ne 0 ]; then
    echo "file-size: self-test: $failures case(s) failed" >&2
    return 1
  fi
  echo "file-size: self-test OK (a growth, a shrink, a split, a gone file, a new breach, a generated file and --update)"
}

mode=check
files=()
while [ $# -gt 0 ]; do
  case "$1" in
    --files)
      mode=files
      shift
      # A path is the list's key relative to this checkout; a file of another
      # checkout, a worktree say, is that checkout's to measure.
      while [ $# -gt 0 ] && [ "${1#--}" = "$1" ]; do
        case "$1" in
          /*) [ "${1#"$PWD"/}" != "$1" ] && files+=("${1#"$PWD"/}") ;;
          *) files+=("$1") ;;
        esac
        shift
      done
      ;;
    --update) mode=update; shift ;;
    --self-test) self_test; exit $? ;;
    *) printf 'usage: %s [--files FILE... | --update | --self-test]\n' "$0" >&2; exit 2 ;;
  esac
done

if [ "$mode" != files ]; then
  while IFS= read -r f; do files+=("$f"); done < <(git ls-files -- '*.rs' ':(exclude)docs/specs/**')
fi

hand_written() {
  case "$1" in docs/specs/* | */docs/specs/*) return 1 ;; esac
  ! head -n1 "$1" | grep -q '@generated'
}

# The allow-list entry of a path, as "<lines> <issue>", or nothing (bash 3.2
# has no associative arrays, so the list is read per lookup).
listed() {
  [ -f "$ALLOW" ] || return 0
  awk -v p="$1" '$1 !~ /^#/ && $2 == p { print $1, $3 }' "$ALLOW"
}

fail=0
grew=0
fell=0
breaches=()
# A listed path that no longer exists was split away: a fall.
if [ "$mode" != files ] && [ -f "$ALLOW" ]; then
  while IFS=' ' read -r first path _; do
    case "$first" in '' | \#*) continue ;; esac
    [ -f "$path" ] && continue
    fell=$((fell + 1))
  done <"$ALLOW"
fi
for f in ${files[@]+"${files[@]}"}; do
  [ -f "$f" ] || continue
  hand_written "$f" || continue
  n=$(wc -l <"$f" | tr -d " ")
  if [ "$n" -gt "$BUDGET" ]; then
    breaches+=("$n $f")
  fi
  entry=$(listed "$f")
  if [ -n "$entry" ]; then
    recorded=${entry%% *}
    tag=${entry#* }
    if [ "$n" -gt "$recorded" ]; then
      note "FAIL $f: $n lines, listed at $recorded ($tag); a listed file may not grow, split it by concern"
      fail=1
      grew=1
    elif [ "$n" -lt "$recorded" ]; then
      fell=$((fell + 1))
    fi
    continue
  fi
  if [ "$n" -gt "$BUDGET" ]; then
    note "FAIL $f: $n lines, over the budget of $BUDGET; split it by concern into a module folder"
    fail=1
  fi
done

if [ "$mode" = update ]; then
  if [ "$grew" -ne 0 ]; then
    note "--update never raises an entry: split the file that grew"
    exit 1
  fi
  out=()
  for b in ${breaches[@]+"${breaches[@]}"}; do
    n=${b%% *}
    p=${b#* }
    entry=$(listed "$p")
    if [ -z "$entry" ]; then
      printf 'file-size: %s is a new breach of %s lines; split it, the list never takes a new entry from --update\n' "$p" "$BUDGET" >&2
      exit 2
    fi
    out+=("$n $p ${entry#* }")
  done
  {
    # REUSE-IgnoreStart
    printf '# SPDX-FileCopyrightText: Cadasto B.V.\n'
    printf '# SPDX-License-Identifier: BUSL-1.1\n'
    # REUSE-IgnoreEnd
    printf '# Known breaches of the %s-line file budget: "<lines> <path> #<issue>".\n' "$BUDGET"
    printf '# A listed file passes while it does not grow past its recorded count;\n'
    printf '# the split removes the entry. scripts/checks/file-size.sh --update lowers it.\n'
    if [ "${#out[@]}" -gt 0 ]; then printf '%s\n' "${out[@]}" | sort -k2; fi
  } >"$ALLOW.tmp" && mv "$ALLOW.tmp" "$ALLOW"
  note "recorded ${#out[@]} breaches in $ALLOW"
  exit 0
fi

if [ "$fail" -eq 0 ]; then
  if [ "$mode" != files ]; then
    note "OK: no hand-written .rs file over $BUDGET lines outside $ALLOW"
  fi
  if [ "$fell" -gt 0 ]; then
    note "note: $fell listed file(s) shrank, split or went; the scheduled ratchet-tighten workflow lowers $ALLOW."
  fi
fi
exit "$fail"
